    btnDismiss.type = 'button';
    // Primary action: confirm the restore (dismiss this prompt).
    btnDismiss.className = '';
    btnDismiss.textContent = '确认还原';
    btnDismiss.addEventListener('click', () => hideRedoOffer());

    const btnRedo = document.createElement('button');
    btnRedo.type = 'button';
    // Secondary action: undo the restore by re-applying the checkpoint edits.
    btnRedo.className = 'ghost';
    btnRedo.textContent = '撤销还原';
